                continue
            boundary = set()
            for y,x in comp:
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1:
                        boundary.add((ny,nx))
            if not boundary:
                continue
            inside = set(comp)
            for y,x in comp:
