def transform(grid):
    n = len(grid[0])
    center = next(c for c, value in enumerate(grid[0]) if value == 2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        lo, hi = center - r, center + r
        for c in range(max(0, lo), min(n - 1, hi) + 1):
